package com.internhub.entity;
import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.DBRef; import org.springframework.data.mongodb.core.mapping.Document;
@Document("company_profiles") public class CompanyProfile {
 @Id private Long id; @Indexed(unique=true) private Long userId; @DBRef private User user; @NotBlank @Size(max=180) private String companyName; private String description; private String website; private String industry; private String contactInformation;
 public Long getId(){return id;} public void setId(Long v){id=v;} public Long getUserId(){return userId;} public User getUser(){return user;} public void setUser(User v){user=v;userId=v==null?null:v.getId();} public String getCompanyName(){return companyName;} public void setCompanyName(String v){companyName=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getWebsite(){return website;} public void setWebsite(String v){website=v;} public String getIndustry(){return industry;} public void setIndustry(String v){industry=v;} public String getContactInformation(){return contactInformation;} public void setContactInformation(String v){contactInformation=v;}
}
